export const partyTopics = { economy: 'Économie et travail', security: 'Sécurité et justice', immigration: 'Immigration et citoyenneté', ecology: 'Écologie et énergie' };
export const partyReviewDate = '2026-11-02';

// Les chiffres de groupes sont dans parliament.json. Aucun total de groupe
// n’est réétiqueté ici comme un effectif propre au parti.
const make = p => ({ ...p, aliases: p.aliases || [], academicRefs: p.academicRefs || ['remond', 'julliard-gauches'],
  issues: Object.fromEntries(Object.keys(partyTopics).map((key, i) => [key, { text: p.positions[i], sourceIds: p.topicSources?.[key] || ['programme'] }])),
  sources: [{ id: 'programme', title: p.programme[0], url: p.programme[1], kind: p.id === 'lo' ? 'Article journalistique' : 'Texte de la formation', context: p.programme[2] || 'Document consulté le 2 novembre 2026 ; synthèse des positions, pas une attribution automatique d’un programme présidentiel complet.' },
    { id: 'histoire', title: p.historySource[0], url: p.historySource[1], kind: 'Repère historique', context: 'À lire avec la bibliographie historique : une histoire officielle est aussi une présentation de soi.' }, ...(p.extraSources || [])],
});

